function startCollection(c){const ids=arr(c.payload&&c.payload.items).map(x=>typeof x==='string'?x:x.id).filter(Boolean),items=ids.map(byId).filter(Boolean);if(!items.length){toast('THIS COLLECTION HAS NO PLAYABLE ITEMS',true);return;}playQueue=items;playQueueIndex=0;jwrite('nd_workshop_play_queue_v1',{id:c.id,items:ids,index:0});selected=null;recordPlay(c);playCreation(items[0]);}
