function surprise(){const list=arr(catalog.creations).filter(c=>['race','battle','curve','challenge'].includes(c.kind));if(!list.length){toast('NO PLAYABLE COMMUNITY LEVELS YET',true);return;}const weighted=list.filter(c=>(Number(c.stats&&c.stats.plays)||0)>=0);selected=weighted[Math.floor(Math.random()*weighted.length)];render();}

function addToCollection(c){openMini('SAVE TO COLLECTION','Create a folder name or reuse one you already have.','<input id="ndwCollectionName" maxlength="32" placeholder="Favorites with friends"><button id="ndwCollectionGo">SAVE</button>');setTimeout(()=>{const go=$('ndwCollectionGo');if(go)go.onclick=()=>{const name=text($('ndwCollectionName').value).slice(0,32);if(!name){toast('NAME THE COLLECTION',true);return;}const col=collections();col.folders=obj(col.folders);col.folders[name]=arr(col.folders[name]);if(!col.folders[name].includes(c.id))col.folders[name].push(c.id);jwrite(LS.collections,col);closeMini();toast('SAVED TO '+name.toUpperCase());};},0);}
