function ensureBuilder(){if(builderModal)return;builderModal=document.createElement('div');builderModal.className='ndw-modal';builderModal.id='ndwBuilderModal';builderModal.innerHTML='<div class="ndw-dialog"><button class="ndw-x" id="ndwBuilderX">×</button><h2 id="ndwBuilderTitle"></h2><label>NAME<input id="ndwBuilderName" maxlength="48"></label><div class="ndw-builditems" id="ndwBuilderItems"></div><div class="ndw-actions"><button id="ndwBuilderSave">SAVE LOCALLY</button><button id="ndwBuilderPublish">PUBLISH</button></div></div>';document.body.appendChild(builderModal);$('ndwBuilderX').onclick=()=>builderModal.classList.remove('show');$('ndwBuilderSave').onclick=()=>saveBuilder(false);$('ndwBuilderPublish').onclick=()=>saveBuilder(true);}
function saveBuilder(pub){const type=builderModal.dataset.type,name=text($('ndwBuilderName').value).slice(0,48)||('MY '+type.toUpperCase()),items=[...builderModal.querySelectorAll('[data-buildid]:checked')].map(x=>x.dataset.buildid).slice(0,type==='cup'?12:40);if(!items.length){toast('ADD AT LEAST ONE CREATION',true);return;}const cols=collections(),key=type==='cup'?'__cupDraft':'__playlistDraft';cols[key]={name,items,updatedAt:nowIso()};jwrite(LS.collections,cols);toast(type.toUpperCase()+' SAVED');if(pub){builderModal.classList.remove('show');openPublish(type,{items},{title:name,kind:type});}}
