function ensureChallengeMaker(){if($('ndwChallengeModal'))return;const m=document.createElement('div');m.className='ndw-modal';m.id='ndwChallengeModal';m.innerHTML='<div class="ndw-dialog"><button class="ndw-x" id="ndwChX">×</button><h2>CHALLENGE MAKER</h2><label>TITLE<input id="ndwChTitle" maxlength="48" value="MY CHALLENGE"></label><label>BASE COMMUNITY LEVEL<select id="ndwChBase"></select></label><div class="ndw-formgrid"><label>OBJECTIVE<select id="ndwChObj"><option value="finish">FINISH LEVEL</option><option value="time">FINISH UNDER TIME</option><option value="coins">COLLECT COINS</option><option value="nofall">FINISH WITHOUT FALLING</option><option value="win">WIN BATTLE</option><option value="survive">SURVIVE SECONDS</option></select></label><label>TARGET<input id="ndwChTarget" type="number" min="0" max="9999" value="60"></label></div><label>CREATOR RULES<textarea id="ndwChRules" rows="3" placeholder="Optional note, e.g. No items, low gravity"></textarea></label><div class="ndw-actions"><button id="ndwChPublish">PUBLISH CHALLENGE</button></div></div>';document.body.appendChild(m);$('ndwChX').onclick=()=>m.classList.remove('show');$('ndwChPublish').onclick=()=>{const base=$('ndwChBase').value;if(!base){toast('PICK A BASE LEVEL',true);return;}const title=text($('ndwChTitle').value).slice(0,48)||'MY CHALLENGE',objective={type:$('ndwChObj').value,target:clamp($('ndwChTarget').value,0,9999),note:text($('ndwChRules').value).slice(0,160)};m.classList.remove('show');openPublish('challenge',{baseCreationId:base,objective,rules:captureRules()},{title,kind:'challenge'});};}
