function showAwards(){tab='awards';creatorView=null;selected=null;const a=arr(catalog.awards);$('ndwTitle').textContent='CREATOR AWARDS';$('ndwGrid').innerHTML='<section class="ndw-special"><h2>🏆 NEON CREATOR AWARDS</h2><p>Weekly awards are calculated from public plays, ratings, likes and remixes.</p><div class="ndw-awards">'+(a.length?a.slice().reverse().map(x=>'<article><b>'+esc(x.title||x.type||'AWARD')+'</b><span>'+esc(x.week||x.at||'')+'</span><button data-awardcreation="'+esc(x.creationId||'')+'">'+esc(x.creationTitle||x.creatorName||'VIEW')+'</button></article>').join(''):'<div class="ndw-empty">Awards begin after community creations are published.</div>')+'</div></section>';document.querySelectorAll('[data-awardcreation]').forEach(b=>b.onclick=()=>{selected=byId(b.dataset.awardcreation);if(selected)render();});}
