function showCollections(){tab='collections';creatorView=null;selected=null;const col=collections();$('ndwTitle').textContent='CUPS & PLAYLISTS';$('ndwGrid').innerHTML='<section class="ndw-special"><h2>BUILD A SET OF COMMUNITY CREATIONS</h2><div class="ndw-bigchoices"><button id="ndwCupBuild">🏆 COMMUNITY CUP<small>Up to 12 levels in an ordered competitive set</small></button><button id="ndwPlaylistBuild">▶ PLAYLIST<small>Save a longer collection for friends or party play</small></button></div><div class="ndw-localbox"><h3>COLLECTION FOLDERS</h3>'+Object.entries(obj(col.folders)).map(([n,ids])=>'<div style="padding:6px 0;border-bottom:1px solid rgba(255,255,255,.08)"><b>'+esc(n)+'</b> · '+arr(ids).length+' creation'+(arr(ids).length===1?'':'s')+'</div>').join('')+(Object.keys(obj(col.folders)).length?'':'<div class="ndw-muted">Save a creation to start a collection folder.</div>')+'<h3>LOCAL CUP / PLAYLIST DRAFTS</h3><pre>'+esc(JSON.stringify({cup:col.__cupDraft||null,playlist:col.__playlistDraft||null},null,2))+'</pre></div></section>';$('ndwCupBuild').onclick=()=>openBuilder('cup');$('ndwPlaylistBuild').onclick=()=>openBuilder('playlist');}

function showcaseCenter(){try{if(typeof player!=='undefined'&&player)return{x:Number(player.x)||0,y:(Number(player.y)||0)+45,z:Number(player.z)||0};if(typeof arenaBound!=='undefined'&&arenaBound)return{x:(arenaBound.minX+arenaBound.maxX)/2,y:40,z:(arenaBound.minZ+arenaBound.maxZ)/2};if(typeof centerline!=='undefined'&&Array.isArray(centerline)&&centerline.length){let minX=Infinity,maxX=-Infinity,minZ=Infinity,maxZ=-Infinity,sy=0;for(const p of centerline){minX=Math.min(minX,p.x);maxX=Math.max(maxX,p.x);minZ=Math.min(minZ,p.z);maxZ=Math.max(maxZ,p.z);sy+=Number(p.y)||0;}return{x:(minX+maxX)/2,y:sy/centerline.length+40,z:(minZ+maxZ)/2};}}catch(e){}return{x:0,y:40,z:0};}
function ensureShowcase(){if(showcase)return;showcase=document.createElement('div');showcase.id='ndwShowcase';showcase.innerHTML='<div class="ndw-showcase-tip">DRAG TO ORBIT · WHEEL TO ZOOM</div><div class="ndw-showcasebar"><button id="ndwShowcaseUp">HEIGHT +</button><button id="ndwShowcaseDown">HEIGHT −</button><button id="ndwShowcaseNear">ZOOM +</button><button id="ndwShowcaseFar">ZOOM −</button><button id="ndwShowcaseReset">RESET</button><button id="ndwShowcaseShot">📷 SCREENSHOT</button><button id="ndwShowcaseCover">USE AS COVER</button><button id="ndwShowcaseExit">EXIT</button></div>';document.body.appendChild(showcase);let drag=false,lx=0,ly=0;showcase.addEventListener('pointerdown',e=>{if(e.target.closest('button'))return;drag=true;lx=e.clientX;ly=e.clientY;try{showcase.setPointerCapture(e.pointerId);}catch(_){}});showcase.addEventListener('pointermove',e=>{if(!drag)return;const dx=e.clientX-lx,dy=e.clientY-ly;lx=e.clientX;ly=e.clientY;showcaseYaw-=dx*.006;showcasePitch=clamp(showcasePitch+dy*.004,-.15,1.15);});showcase.addEventListener('pointerup',()=>drag=false);showcase.addEventListener('wheel',e=>{e.preventDefault();showcaseRadius=clamp(showcaseRadius*(e.deltaY>0?1.08:.92),180,6000);},{passive:false});$('ndwShowcaseUp').onclick=()=>showcaseHeight+=40;$('ndwShowcaseDown').onclick=()=>showcaseHeight-=40;$('ndwShowcaseNear').onclick=()=>showcaseRadius=clamp(showcaseRadius*.8,180,6000);$('ndwShowcaseFar').onclick=()=>showcaseRadius=clamp(showcaseRadius*1.25,180,6000);$('ndwShowcaseReset').onclick=resetShowcase;$('ndwShowcaseShot').onclick=async()=>{const d=await coverCapture();if(!d){toast('NO 3D VIEW TO CAPTURE',true);return;}const a=document.createElement('a');a.href=d;a.download='neon-drift-showcase-'+Date.now()+'.webp';a.click();toast('SHOWCASE IMAGE SAVED');};$('ndwShowcaseCover').onclick=async()=>{const d=await coverCapture();if(!d){toast('NO 3D VIEW TO CAPTURE',true);return;}if(publishDraft){publishDraft.coverData=d;toast('PUBLISH COVER UPDATED');}else{jwrite('nd_workshop_last_showcase_cover_v1',{data:d,at:Date.now()});toast('SHOWCASE COVER SAVED FOR YOUR NEXT PUBLISH');}};$('ndwShowcaseExit').onclick=closeShowcase;}
function resetShowcase(){showcaseTarget=showcaseCenter();showcaseYaw=.6;showcasePitch=.28;showcaseRadius=900;showcaseHeight=0;try{if(typeof arenaBound!=='undefined'&&arenaBound){const w=arenaBound.maxX-arenaBound.minX,d=arenaBound.maxZ-arenaBound.minZ;showcaseRadius=Math.max(550,Math.max(w,d)*.62);}else if(typeof centerline!=='undefined'&&centerline.length){let minX=Infinity,maxX=-Infinity,minZ=Infinity,maxZ=-Infinity;for(const p of centerline){minX=Math.min(minX,p.x);maxX=Math.max(maxX,p.x);minZ=Math.min(minZ,p.z);maxZ=Math.max(maxZ,p.z);}showcaseRadius=Math.max(550,Math.max(maxX-minX,maxZ-minZ)*.65);}}catch(e){}}
function renderShowcase(){if(!showcaseActive)return;try{if(typeof camera!=='undefined'&&camera&&typeof renderer!=='undefined'&&renderer&&typeof scene!=='undefined'&&scene){const t=showcaseTarget||showcaseCenter(),cp=Math.cos(showcasePitch),sp=Math.sin(showcasePitch),sy=Math.sin(showcaseYaw),cy=Math.cos(showcaseYaw);camera.position.set(t.x+sy*cp*showcaseRadius,t.y+sp*showcaseRadius+showcaseHeight,t.z+cy*cp*showcaseRadius);camera.lookAt(t.x,t.y+showcaseHeight*.18,t.z);camera.updateProjectionMatrix();renderer.render(scene,camera);}}catch(e){}requestAnimationFrame(renderShowcase);}
function openShowcase(){try{if(typeof camera==='undefined'||!camera||typeof renderer==='undefined'||!renderer){toast('3D VIEW IS NOT READY YET',true);return;}ensureShowcase();showcaseSaved={screens:[...document.querySelectorAll('.screen')].map(x=>[x,!x.classList.contains('hide')]),camPos:camera.position.clone(),camQuat:camera.quaternion.clone(),fov:camera.fov};document.querySelectorAll('.screen').forEach(x=>x.classList.add('hide'));showcase.classList.add('show');showcaseActive=true;resetShowcase();requestAnimationFrame(renderShowcase);}catch(e){console.warn(e);toast('SHOWCASE MODE COULD NOT OPEN',true);}}
function closeShowcase(){if(!showcaseActive)return;showcaseActive=false;if(showcase)showcase.classList.remove('show');try{if(showcaseSaved){for(const [x,was] of showcaseSaved.screens){if(was)x.classList.remove('hide');else x.classList.add('hide');}if(typeof camera!=='undefined'&&camera){camera.position.copy(showcaseSaved.camPos);camera.quaternion.copy(showcaseSaved.camQuat);camera.fov=showcaseSaved.fov;camera.updateProjectionMatrix();}}}catch(e){}showcaseSaved=null;if(publishDraft&&publishModal)publishModal.classList.add('show');}
