 screen=document.createElement('div');screen.id='ndWorkshopScreen';screen.className='screen hide';screen.innerHTML='<div class="ndw-shell"><div class="ndw-top"><button class="ghost" id="ndwBack">← GAME</button><div class="ndw-logo">NEON WORKSHOP</div><input id="ndwSearch" placeholder="Search creations or creators"><select id="ndwKind"><option value="all">ALL TYPES</option>'+KINDS.map(k=>'<option value="'+k+'">'+humanKind(k)+'</option>').join('')+'</select><button id="ndwSurprise">🎲 SURPRISE ME</button><button id="ndwPublish">＋ PUBLISH</button><button id="ndwImport">IMPORT CODE</button><button id="ndwShowcaseOpen">📷 SHOWCASE</button><button id="ndwSync">SYNC</button><button id="ndwRefresh">↻</button></div><nav class="ndw-nav">'+[['featured','FEATURED'],['trending','TRENDING'],['new','NEW'],['top','TOP RATED'],['played','MOST PLAYED'],['following','FOLLOWING'],['friends','FRIENDS'],['favorites','FAVORITES'],['mine','MY WORK'],['challenges','CHALLENGES'],['collections','CUPS / PLAYLISTS'],['awards','AWARDS']].map(x=>'<button class="ndw-tab" data-tab="'+x[0]+'">'+x[1]+'</button>').join('')+'</nav><div class="ndw-heading"><h1 id="ndwTitle">FEATURED</h1><small id="ndwUpdated">COMMUNITY CATALOG</small></div><main class="ndw-grid" id="ndwGrid"></main></div>';document.body.appendChild(screen);toastEl=document.createElement('div');toastEl.className='ndw-toast';document.body.appendChild(toastEl);
 $('ndwBack').onclick=closeWorkshop;$('ndwSearch').oninput=e=>{query=e.target.value;render();};$('ndwKind').onchange=e=>{kindFilter=e.target.value;render();};$('ndwSurprise').onclick=surprise;$('ndwPublish').onclick=()=>openPublish('race');$('ndwImport').onclick=openImport;$('ndwShowcaseOpen').onclick=openShowcase;$('ndwSync').onclick=syncEvents;$('ndwRefresh').onclick=()=>loadCommunity(true);document.querySelectorAll('.ndw-tab').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;creatorView=null;selected=null;if(tab==='awards')showAwards();else if(tab==='challenges')showChallenges();else if(tab==='collections')showCollections();else render();});
 const photo=document.createElement('button');photo.id='ndwQuickPhoto';photo.className='ndw-photo-btn';photo.textContent='📷 SHOWCASE PHOTO';photo.onclick=async()=>{const d=await coverCapture();if(d){const a=document.createElement('a');a.href=d;a.download='neon-drift-showcase-'+Date.now()+'.webp';a.click();toast('SHOWCASE PHOTO SAVED');}};document.body.appendChild(photo);
